#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn villager_type_catalog_is_complete_ordered_and_unique() {
        assert_eq!(VANILLA_VILLAGER_TYPES.len(), 7);
        let mut resources = HashSet::new();
        for (registry_id, entry) in VANILLA_VILLAGER_TYPES.iter().enumerate() {
            assert_eq!(entry.villager_type as usize, registry_id);
            assert!(resources.insert(entry.resource_id));
            assert_eq!(entry.villager_type.vanilla_registry_index(), registry_id);
        }
    }

    #[test]
    fn villager_type_catalog_preserves_registry_and_resource_order() {
        assert_eq!(
            VillagerModelType::for_vanilla_registry_id(0),
            Some(VillagerModelType::Desert)
        );
        assert_eq!(
            VillagerModelType::for_vanilla_registry_id(6),
            Some(VillagerModelType::Taiga)
        );
        assert_eq!(VillagerModelType::for_vanilla_registry_id(-1), None);
        assert_eq!(VillagerModelType::for_vanilla_registry_id(7), None);
        assert_eq!(
            VillagerModelType::for_resource_id("minecraft:plains"),
            Some(VillagerModelType::Plains)
        );
        assert_eq!(VillagerModelType::for_resource_id("minecraft:coast"), None);
        assert_eq!(VillagerModelType::Snow.resource_id(), "minecraft:snow");
    }

    #[test]
    fn production_sources_do_not_redeclare_villager_type_facts() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/villager_model_types.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                if source.contains("enum VillagerModelType")
                    || source.contains("fn villager_type_from_entry_id(")
                    || source.contains("fn villager_type_from_vanilla_registry_id(")
                    || source.contains("fn villager_type_index(")
                    || source.contains("fn vanilla_villager_type_resource_id(")
                    || source.contains("const VANILLA_VILLAGER_TYPE_KEYS")
                    || source.contains("\"minecraft:desert\" => Some(VillagerModelType::")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel villager-type catalog owners: {violations:?}"
        );
    }
}
